const t0 = Date.now();
const s = $input.first().json;
const errores = [];
if (!s.caso_id) errores.push('Falta caso_id');
if (!s.solicitud || !String(s.solicitud).trim()) errores.push('Falta solicitud');
if (s.modo !== 'SIMULADO') errores.push('Modo fuera de politica: solo se permite SIMULADO');
if (s.objetivo !== 'cotizar_productos') errores.push('Objetivo fuera de politica: solo cotizar_productos');
const limite = Number(s.limite_costo_usd);
if (!(limite > 0) || limite > 1) errores.push('limite_costo_usd invalido o fuera de politica (0 < x <= 1)');
const ok = errores.length === 0;
const traza = {
  caso_id: s.caso_id || null,
  agente: 'ORQUESTADOR',
  etapa: 'apertura_y_validacion_de_caso',
  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? 'Caso valido y dentro de politica (SIMULADO, cotizar_productos). Se asigna tarea al Agente 1.' : errores.join('; '),
  fuentes: ['Datos iniciales'],
  advertencias: [],
  duracion_ms: Date.now() - t0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista: no consume tokens.' }
};
return [{ json: {
  caso_id: s.caso_id, canal: s.canal, usuario: s.usuario, objetivo: s.objetivo,
  solicitud: s.solicitud, modo: s.modo, limite_costo_usd: limite,
  estado_flujo: ok ? 'OK' : 'DETENIDO',
  motivo_detencion: ok ? null : errores.join('; '),
  requiere_aclaracion: false,
  advertencias: [],
  trazas: [traza],
  presupuesto: { limite_usd: limite, consumo_usd: null, llamadas_ia_realizadas: 0, estado: 'NO_VERIFICABLE', nota: 'El nodo AI Agent no expone tokens ni costo. Pendiente de configurar (consultar uso en el proveedor o usar un callback de uso). Se limita el gasto con maxTokens en cada modelo.' },
  _t_inicio: t0,
  _t_prep: Date.now()
} }];

const prev = $('Orquestador 1 - Abrir y validar caso').first().json;
const out = $input.first().json.output || {};
const dur = Date.now() - prev._t_prep;
const adv = Array.isArray(out.advertencias) ? out.advertencias.slice() : [];
const prods = Array.isArray(out.productos) ? out.productos : [];
const faltante = Array.isArray(out.informacion_faltante) ? out.informacion_faltante : [];
let estadoFlujo = 'OK';
let motivo = null;
let aclaracion = false;
if (out.caso_id !== prev.caso_id) {
  estadoFlujo = 'DETENIDO'; motivo = 'caso_id inconsistente: Agente 1 devolvio ' + out.caso_id + ' y el caso es ' + prev.caso_id;
} else if (out.requiere_aclaracion === true || faltante.length > 0) {
  estadoFlujo = 'DETENIDO'; aclaracion = true; motivo = 'Solicitud incompleta, se requiere aclaracion: ' + (out.pregunta_aclaracion || faltante.join('; '));
} else if (prods.length === 0) {
  estadoFlujo = 'DETENIDO'; motivo = 'El Agente 1 no extrajo ningun producto';
} else {
  for (const p of prods) {
    const q = Number(p.cantidad);
    if (!p.nombre || !(q > 0) || Math.floor(q) !== q) { estadoFlujo = 'DETENIDO'; aclaracion = true; motivo = 'Producto o cantidad invalida: ' + JSON.stringify(p); break; }
    if (!String(prev.solicitud).includes(String(q))) { estadoFlujo = 'DETENIDO'; motivo = 'Cantidad ' + q + ' no aparece en la solicitud original (posible dato inventado)'; break; }
  }
}
const ok = estadoFlujo === 'OK';
const trazaAg = {
  caso_id: prev.caso_id, agente: 'AGENTE_1_VALIDACION', etapa: 'validacion_de_solicitud',
  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? { productos: prods } : motivo,
  fuentes: ['solicitud original del caso'], advertencias: adv, duracion_ms: dur,
  referencia_consumo: { execution_id: $execution.id, nodo: 'Agente 1 - Validacion de solicitudes', modelo: 'gpt-5-mini (Gateway credits)', tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Tokens/costo no expuestos por el nodo AI Agent: pendiente de configurar.' }
};
const trazaOrq = {
  caso_id: prev.caso_id, agente: 'ORQUESTADOR', etapa: 'revision_agente_1',
  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? 'Salida de Agente 1 valida, mismo caso_id, cantidades presentes en la solicitud. Se asigna Agente 2.' : 'Proceso detenido: ' + motivo,
  fuentes: ['Agente 1'], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista.' }
};
return [{ json: Object.assign({}, prev, {
  estado_flujo: estadoFlujo, motivo_detencion: motivo, requiere_aclaracion: aclaracion,
  agente1: out,
  advertencias: prev.advertencias.concat(adv),
  trazas: prev.trazas.concat([trazaAg, trazaOrq]),
  presupuesto: Object.assign({}, prev.presupuesto, { llamadas_ia_realizadas: prev.presupuesto.llamadas_ia_realizadas + 1 }),
  _t_prep: Date.now()
}) }];

const s = $input.first().json;
const catalogo = {
  fuente: 'catalogo_ficticio_logismart_v1',
  moneda: 'MXN',
  productos: {
    a: { nombre: 'Producto A', precio: 120, inventario: 100 },
    b: { nombre: 'Producto B', precio: 85, inventario: 80 }
  }
};
const trazaOrq = {
