const prev = $('Calculo determinista de cotizacion').first().json;
const out = $input.first().json.output || {};
const dur = Date.now() - prev._t_prep;
const c = prev.cotizacion;
const norm = function (x) { return String(x || '').toLowerCase().replace('producto', '').trim(); };
const adv = Array.isArray(out.advertencias) ? out.advertencias.slice() : [];
const errores = [];
if (out.caso_id !== prev.caso_id) errores.push('caso_id inconsistente en Agente 3: ' + out.caso_id);
const lin = Array.isArray(out.lineas) ? out.lineas : [];
if (lin.length !== c.lineas.length) errores.push('El numero de lineas de la propuesta no coincide con el calculo');
for (const l of c.lineas) {
  const m = lin.find(function (x) { return norm(x.producto) === norm(l.producto); });
  if (!m) { errores.push('Falta la linea de ' + l.producto + ' en la propuesta'); continue; }
  if (Number(m.cantidad) !== l.cantidad || Number(m.precio_unitario) !== l.precio_unitario || Number(m.subtotal) !== l.subtotal) errores.push('Cifras alteradas en la linea de ' + l.producto);
}
if (Number(out.subtotal) !== c.subtotal) errores.push('Subtotal de la propuesta (' + out.subtotal + ') difiere del calculo (' + c.subtotal + ')');
if (Number(out.total) !== c.total) errores.push('Total de la propuesta (' + out.total + ') difiere del calculo (' + c.total + ')');
if (Number(out.impuestos) !== 0 || Number(out.envio) !== 0 || Number(out.descuentos) !== 0) errores.push('La propuesta incluye impuestos, envio o descuentos no autorizados');
if (out.moneda !== c.moneda) errores.push('Moneda inconsistente en la propuesta');
const ok = errores.length === 0;
const motivo = ok ? null : errores.join('; ');
const trazaAg = {
  caso_id: prev.caso_id, agente: 'AGENTE_3_COTIZACION', etapa: 'elaboracion_de_cotizacion',
  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? { subtotal: out.subtotal, total: out.total, moneda: out.moneda } : motivo,
  fuentes: [c.fuente, 'Calculo determinista de cotizacion'], advertencias: adv, duracion_ms: dur,
  referencia_consumo: { execution_id: $execution.id, nodo: 'Agente 3 - Elaboracion de cotizacion', modelo: 'gpt-5-mini (Gateway credits)', tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Tokens/costo no expuestos por el nodo AI Agent: pendiente de configurar.' }
};
const trazaOrq = {
  caso_id: prev.caso_id, agente: 'ORQUESTADOR', etapa: 'revision_agente_3',
  estado: ok ? 'COMPLETADO' : 'DETENIDO',
  resultado: ok ? 'Propuesta coincide con el calculo determinista. Se asigna control de calidad.' : 'Proceso detenido: ' + motivo,
  fuentes: ['Agente 3', 'Calculo determinista'], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista.' }
};
return [{ json: Object.assign({}, prev, {
  estado_flujo: ok ? 'OK' : 'DETENIDO', motivo_detencion: motivo,
  agente3: out,
  advertencias: prev.advertencias.concat(adv),
  trazas: prev.trazas.concat([trazaAg, trazaOrq]),
  presupuesto: Object.assign({}, prev.presupuesto, { llamadas_ia_realizadas: prev.presupuesto.llamadas_ia_realizadas + 1 }),
  _t_prep: Date.now()
}) }];

const s = $input.first().json;
const c = s.cotizacion;
const a3 = s.agente3;
const cat = s.catalogo;
const norm = function (x) { return String(x || '').toLowerCase().replace('producto', '').trim(); };
const r2 = function (n) { return Math.round(n * 100) / 100; };
const checks = [];
const chk = function (id, descripcion, ok, detalle) { checks.push({ id: id, descripcion: descripcion, ok: !!ok, detalle: detalle || '' }); };
chk('caso_id_consistente', 'El caso_id es el mismo en el Agente 1, 2 y 3', [s.agente1.caso_id, s.agente2.caso_id, a3.caso_id, c.caso_id].every(function (x) { return x === s.caso_id; }));
chk('productos_y_cantidades', 'Productos y cantidades de la cotizacion coinciden con lo extraido por el Agente 1', s.agente1.productos.every(function (p) {
  const l = c.lineas.find(function (x) { return norm(x.producto) === norm(p.nombre); });
  return l && l.cantidad === Number(p.cantidad);
}) && s.agente1.productos.length === c.lineas.length);
chk('precios_vs_catalogo', 'Cada precio unitario coincide con el catalogo autorizado', c.lineas.every(function (l) {
  const k = norm(l.producto); return cat.productos[k] && cat.productos[k].precio === l.precio_unitario;
}));
chk('inventario_suficiente', 'Ninguna cantidad supera el inventario autorizado', c.lineas.every(function (l) {
  const k = norm(l.producto); return cat.productos[k] && l.cantidad <= cat.productos[k].inventario;
}));
chk('subtotales', 'Cada subtotal = cantidad x precio unitario', c.lineas.every(function (l) { return r2(l.cantidad * l.precio_unitario) === l.subtotal; }));
chk('total', 'El total = suma de subtotales', r2(c.lineas.reduce(function (a, l) { return a + l.subtotal; }, 0)) === c.total && c.total === c.subtotal);
chk('sin_extras', 'No hay impuestos, envio ni descuentos inventados (cotizacion y propuesta)', c.impuestos === 0 && c.envio === 0 && c.descuentos === 0 && Number(a3.impuestos) === 0 && Number(a3.envio) === 0 && Number(a3.descuentos) === 0);
chk('propuesta_coincide_calculo', 'La propuesta del Agente 3 tiene el mismo total y moneda que el calculo', Number(a3.total) === c.total && a3.moneda === c.moneda);
chk('fuente_catalogo', 'La fuente del catalogo esta presente y coincide', c.fuente === cat.fuente && s.agente2.fuente === cat.fuente);
chk('politica', 'Modo SIMULADO y moneda MXN', s.modo === 'SIMULADO' && c.moneda === 'MXN');
const trazaOrq = {
  caso_id: s.caso_id, agente: 'ORQUESTADOR', etapa: 'validaciones_deterministas_qa',
  estado: 'COMPLETADO',
  resultado: checks.filter(function (x) { return x.ok; }).length + ' de ' + checks.length + ' validaciones deterministas aprobadas',
  fuentes: [cat.fuente], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Validaciones deterministas: no consumen tokens.' }
};
return [{ json: Object.assign({}, s, { checks_deterministas: checks, trazas: s.trazas.concat([trazaOrq]), _t_prep: Date.now() }) }];

