const prev = $('Validaciones deterministas QA').first().json;
const out = $input.first().json.output || {};
const dur = Date.now() - prev._t_prep;
const adv = Array.isArray(out.advertencias) ? out.advertencias.slice() : [];
const hallazgos = Array.isArray(out.hallazgos) ? out.hallazgos.slice() : [];
const fallidos = prev.checks_deterministas.filter(function (x) { return !x.ok; });
const problemas = [];
if (out.caso_id !== prev.caso_id) problemas.push('caso_id inconsistente en Agente 4: ' + out.caso_id);
if (out.dictamen !== 'APROBADO_TECNICAMENTE' && out.dictamen !== 'DEVUELTO') problemas.push('Dictamen no reconocido: ' + out.dictamen);
if (out.autoriza_accion_comercial !== false) problemas.push('El Agente 4 intento autorizar una accion comercial (no permitido)');
if (fallidos.length > 0) problemas.push('Validaciones deterministas fallidas: ' + fallidos.map(function (x) { return x.id; }).join(', '));
const aprobado = out.dictamen === 'APROBADO_TECNICAMENTE' && problemas.length === 0;
const dictamen = aprobado ? 'APROBADO_TECNICAMENTE' : 'DEVUELTO';
const revision = {
  dictamen: dictamen,
  dictamen_agente_4: out.dictamen || null,
  hallazgos: hallazgos.concat(problemas),
  validaciones_deterministas: prev.checks_deterministas,
  fuentes_verificadas: Array.isArray(out.fuentes_verificadas) ? out.fuentes_verificadas : [],
  autoriza_accion_comercial: false
};
const trazaAg = {
  caso_id: prev.caso_id, agente: 'AGENTE_4_CONTROL_CALIDAD', etapa: 'control_de_calidad',
  estado: 'COMPLETADO',
  resultado: { dictamen: dictamen, hallazgos: revision.hallazgos },
  fuentes: revision.fuentes_verificadas, advertencias: adv, duracion_ms: dur,
  referencia_consumo: { execution_id: $execution.id, nodo: 'Agente 4 - Control de calidad', modelo: 'gpt-5-mini (Gateway credits)', tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Tokens/costo no expuestos por el nodo AI Agent: pendiente de configurar.' }
};
const trazaOrq = {
  caso_id: prev.caso_id, agente: 'ORQUESTADOR', etapa: 'revision_agente_4',
  estado: aprobado ? 'COMPLETADO' : 'DEVUELTO',
  resultado: aprobado ? 'Dictamen del Agente 4 y validaciones deterministas coinciden: APROBADO_TECNICAMENTE. Pasa a cierre con aprobacion humana pendiente.' : 'Cotizacion DEVUELTA: ' + revision.hallazgos.join('; '),
  fuentes: ['Agente 4', 'Validaciones deterministas QA'], advertencias: [], duracion_ms: 0,
  referencia_consumo: { execution_id: $execution.id, tokens_entrada: null, tokens_salida: null, costo_usd: null, nota: 'Logica determinista.' }
};
return [{ json: Object.assign({}, prev, {
  estado_flujo: aprobado ? 'OK' : 'DEVUELTO',
  motivo_detencion: aprobado ? null : revision.hallazgos.join('; '),
  agente4: out, revision_tecnica: revision,
  advertencias: prev.advertencias.concat(adv),
  trazas: prev.trazas.concat([trazaAg, trazaOrq]),
  presupuesto: Object.assign({}, prev.presupuesto, { llamadas_ia_realizadas: prev.presupuesto.llamadas_ia_realizadas + 1 }),
  _t_prep: Date.now()
}) }];

const s = $input.first().json;
const ahora = Date.now();
const agentesCompletados = s.trazas.filter(function (t) { return String(t.agente).indexOf('AGENTE_') === 0 && t.estado === 'COMPLETADO'; }).map(function (t) { return t.agente; });
const cot = s.cotizacion || null;
const dictamen = s.revision_tecnica ? s.revision_tecnica.dictamen : null;
let estadoFinal;
if (s.estado_flujo === 'DETENIDO') {
  estadoFinal = s.requiere_aclaracion ? 'ACLARACION_REQUERIDA' : 'DETENIDO';
